const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,text,disabled=false,extra='',primary=false)=>`<button class="btn ${primary?'primary':''}" data-action="${action}" ${disabled?'disabled':''} ${extra}>${text}</button>`;
const phase={charge:'マナ',main:'召喚・呪文',attack:'攻撃'};
function cardHTML(c,{art,selected,busy}={},zone='hand'){return `<button class="online-card ${c.tapped?'is-tapped':''} ${selected===c.uid?'selected':''}" data-action="online-card" data-uid="${esc(c.uid)}" ${busy?'disabled':''} aria-pressed="${selected===c.uid}" aria-label="${esc(c.hidden?'裏向きのカード':c.name)}">${!c.hidden&&art?art(c.id):''}<span class="online-card-cost">${esc(c.hidden?'?':c.cost)}</span><strong>${esc(c.hidden?'裏向き':c.name)}</strong>${zone==='battle'?`<small>${c.type==='gear'?'クロスギア · '+(c.crossedTo?'装備中':'未クロス'):esc(c.power||0)} · ${c.tapped?'タップ中':'アンタップ'}${c.under?.length?' · 進化元 '+c.under.length+'枚':''}</small>`:''}</button>`;}
export function onlineScreenHTML(state,{user,decks=[],selectedDeckId,code='',selected=null,page=0,art,actionsOpen=false,valid=()=>true,history=[]}={}){
 const room=state.room,game=room?.game,busy=state.busy,disabled=busy||!state.connected;
 const notice=state.error?`<div class="notice" role="alert">${esc(state.error)} ${button('online-refresh','再接続',busy)}</div>`:'';
 if(!user)return `<div class="page-head"><div><div class="eyebrow">PLAY WITH FRIENDS</div><h1>友達と対戦</h1><p>同じルームに参加して、手札を選んで対戦しよう。</p></div></div><section class="panel online-lobby"><h2>Googleでログインしよう</h2><p>それぞれ別のGoogleアカウントで参加します。</p>${button('nav','アカウントを開く',false,'data-view="account"',true)}</section>`;
 if(room&&room.phase==='waiting'&&room.seat===0)return `<div class="page-head"><div><div class="eyebrow">PRIVATE ROOM</div><h1>友達を待っています</h1><p>相手がデッキを選んで参加すると対戦が始まります。</p></div></div>${notice}<section class="panel online-lobby"><small>ルームコード</small><div class="online-room-code">${esc(room.code.slice(0,8))} ${esc(room.code.slice(8))}</div><div class="row">${button('online-copy-code','コードをコピー')}${button('online-copy-link','招待リンクをコピー')}</div><p>相手もGoogleでログインし、このコードまたは招待リンクから参加してください。</p><p class="small">待機ルームの有効期限は作成から6時間です。手札と山札の中身は相手に表示されません。</p>${button('online-cancel','ルームを閉じる',disabled)}${button('online-refresh',busy?'確認中…':'再接続',busy)}</section>`;
 if(game){const seat=room.seat,own=game.players[seat],opp=game.players[1-seat],finished=['finished','expired'].includes(room.phase),mine=game.actor===seat&&!finished,all=game.actions,filtered=selected?all.filter(a=>a.uid===selected):all,actions=filtered.length?filtered:all,pages=Math.max(1,Math.ceil(actions.length/8)),current=Math.min(page,pages-1),cards=[...own.hand,...own.battle,...own.mana,...own.grave,...opp.battle,...opp.mana,...opp.grave],card=cards.find(x=>x.uid===selected);
 const board=p=>`<section class="online-player ${p===own?'you':'opponent'}"><div class="row spread"><strong>${esc(p.name)} ${p===own?'<span>YOU</span>':''} <small>${(p===own?seat:1-seat)===game.first?'先攻':'後攻'}</small></strong><div class="online-zone-stats">山札 ${p.deckCount} · 手札 ${p.handCount} · シールド <b>${p.shieldCount}</b></div></div><div class="row spread online-public-zones">${button('online-zone',`マナ ${p.mana.length}`,false,`data-player="${p===own?seat:1-seat}" data-zone="mana"`)}${button('online-zone',`墓地 ${p.grave.length}`,false,`data-player="${p===own?seat:1-seat}" data-zone="grave"`)}${p.faceUpShields?.length?button('online-zone',`表向きシールド ${p.faceUpShields.length}`,false,`data-player="${p===own?seat:1-seat}" data-zone="faceUpShields"`):''}</div><div class="online-field">${p.battle.map(c=>cardHTML(c,{art,selected,busy},'battle')).join('')||'<p>クリーチャーはいません</p>'}</div></section>`;
 return `<div class="online-match"><header class="online-match-head"><div><strong>友達と対戦</strong> <span>TURN ${game.turn} · ${esc(phase[game.phase]||'効果の解決')}</span></div><div>${button('online-menu','メニュー')}${button('online-refresh','再接続',busy)}</div></header>${notice}<div class="online-connection" role="status">${finished?room.phase==='expired'?'ルームの有効期限が切れました':game.draw?'引き分け':game.winner===seat?'あなたの勝利！':'相手の勝利':!state.connected?'再接続してください':busy?'送信・更新中…':mine?'あなたの操作':'相手の操作を待っています'}${finished?` · ${esc(game.reason)}`:''}</div><div class="online-board">${board(opp)}<div class="online-vs">VS</div>${board(own)}</div><section class="online-hand"><div class="row spread"><strong>手札 ${own.handCount}</strong>${own.deckTop?button('card-detail','山札の上：'+esc(own.deckTop.name),false,`data-id="${esc(own.deckTop.id)}"`):''}<small>左右にスワイプ・タップして操作</small></div><div class="online-hand-track">${own.hand.map(c=>cardHTML(c,{art,selected,busy})).join('')}</div></section><section class="online-controls"><div class="row spread"><strong>${finished?'対戦終了':mine?(esc(game.decision)||'操作を選ぶ'):'相手の操作中'}</strong>${selected?button('online-all-actions','全操作を表示'):''}</div>${card?`<div class="row"><span>${esc(card.name)}</span>${!card.hidden?button('card-detail','能力を見る',false,`data-id="${esc(card.id)}"`):''}</div>`:''}${button('online-actions-toggle',actionsOpen?'操作を閉じる':'操作する',!mine&&!finished,'',mine)}${actionsOpen?`<div class="online-action-drawer">${game.numberChoice?'<label class="online-number">宣言する数字 <input class="field" id="online-number" inputmode="numeric" value="0" aria-label="宣言する数字"><small>無限を宣言する場合は「∞」</small></label>':''}<div class="online-actions">${actions.slice(current*8,current*8+8).map(a=>button('online-move',esc(a.label),disabled||!mine,`data-index="${a.id}"`,true)).join('')}</div>${pages>1?`<div class="row">${button('online-page','前へ',current===0,`data-page="${current-1}"`)}<span>${current+1} / ${pages}</span>${button('online-page','次へ',current===pages-1,`data-page="${current+1}"`)}</div>`:''}</div>`:''}${finished?button('online-back','ルーム画面へ'):''}</section></div>`;
 }
 const choices=decks.map(d=>`<option value="${esc(d.id)}" ${d.id===selectedDeckId?'selected':''} ${!valid(d)?'disabled':''}>${esc(d.name)}${!valid(d)?'（対戦未対応）':''}</option>`).join(''),hasDeck=decks.some(valid);
 return `<div class="page-head"><div><div class="eyebrow">PLAY WITH FRIENDS</div><h1>友達と対戦</h1><p>ルームコードを共有して、アカウント同士で対戦。</p></div>${button('nav','AI対戦へ',false,'data-view="battle"')}</div>${notice}<div class="online-lobby-grid"><section class="panel online-lobby"><span class="badge green">${esc(user.name)} でログイン中</span><h2>使うデッキ</h2><label>マイデッキから選ぶ<select class="field" id="online-deck" aria-label="オンライン対戦に使うデッキ">${choices||'<option>デッキがありません</option>'}</select></label>${!hasDeck?`<p>40枚すべての効果に対応したデッキが必要です。</p>${button('nav','マイデッキへ',false,'data-view="decks"')}`:''}<p class="small">選んだ構成で対戦します。対戦中に元のデッキを編集しても、盤面には影響しません。</p>${button('online-create',busy?'確認中…':'ルームを作る',busy||!hasDeck,'',true)}</section><section class="panel online-lobby"><h2>友達のルームに参加</h2><label>ルームコード<input class="field" id="online-code" value="${esc(code)}" autocomplete="off" autocapitalize="characters" maxlength="40" placeholder="コピーしたコードを貼り付け" aria-label="ルームコード"></label>${button('online-join','このデッキで参加',busy||!hasDeck,'',true)}${button('online-resume','進行中の対戦を再開',busy)}<p class="small">招待リンクからも参加できます。参加には、それぞれ別のGoogleアカウントが必要です。</p></section></div>${room&&['expired','cancelled','finished'].includes(room.phase)?'<p class="notice">前のルームは終了しています。新しく作成できます。</p>':''}${history.length?`<section class="panel online-lobby"><h2>最近の対戦</h2>${history.slice(0,10).map(h=>`<p>${esc(h.result)} · ${esc(h.opponent)} · ${h.turn}ターン</p>`).join('')}</section>`:''}`;
}
